const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const read = (file) => fs.readFileSync(path.join(root, file), "utf8");

test("auth dialog supports login, registration, and password recovery", () => {
  const html = read("index.html");
  const app = read("app.js");
  const server = read("server.js");

  for (const id of ["authUsername", "btnAuthLogin", "btnAuthRegister", "btnAuthRecover"]) {
    assert.match(html, new RegExp(`id=\"${id}\"`), `missing ${id}`);
  }
  assert.match(app, /\/api\/auth\/signup/);
  assert.match(app, /请在 Edward 桌面应用中完成注册。/);
  assert.match(app, /registerAccount\(email, password, username\)/);
  assert.match(app, /recoverAccount\(email\)/);
  assert.match(app, /请在 Edward 桌面应用中发起密码找回。/);
  assert.match(server, /\/api\/auth\/recover/);
  assert.match(server, /\/auth\/v1\/recover/);
});

test("settings expose five Edward tabs and their controls", () => {
  const html = read("index.html");
  const app = read("app.js");
  const aiClient = read("ai-client.js");
  const css = read("style.css");
  const settingsClient = read("settings-client.js");

  for (const id of ["settingsTabs", "settingsPathsPanel", "settingsModelsPanel", "settingsPreferencesPanel", "settingsLogsPanel", "settingsFeedbackPanel", "modelProviderList", "modelProviderDetail", "aiProviderCards", "setAiPreset", "providerDetails", "btnShowProviderForm", "btnBackToProviderList", "setAiProviderId", "setAiProvider", "setAiEndpoint", "setAiProtocol", "setAiApiKey", "setAiModel", "setAiModelCatalog", "settingsPathList", "btnTestProvider", "btnFetchModels", "btnAddProvider", "btnCompilePreferences", "btnExportPreferences", "btnImportPreferences", "btnUploadPreferences", "btnDownloadPreferences", "setDiagnosticLog", "btnRefreshDiagnosticLog", "btnReportError", "btnSendFeedback"]) {
    assert.match(html, new RegExp(`id=\"${id}\"`), `missing ${id}`);
  }
  assert.doesNotMatch(html, /id="setShortcutProfile"/);
  assert.doesNotMatch(html, /id="setLinkSelect"/);
  assert.match(app, /window\.edwardSettings\.load\(\)/);
  assert.match(app, /window\.edwardSettings\.save\(/);
  assert.match(app, /window\.edwardSettings\.chooseExportDirectory\(/);
  assert.match(app, /window\.edwardSettings\.compilePreferences\(\)/);
  assert.match(settingsClient, /savePaths:/);
  assert.match(app, /window\.edwardSettings\.migratePath\(/);
  assert.match(app, /项目与输出/);
  assert.match(app, /下载与插件/);
  assert.match(app, /缓存与渲染/);
  assert.match(app, /clear\.textContent="清理"/);
  assert.match(app, /\/api\/settings\/provider-presets/);
  assert.match(app, /provider: "DeepSeek", providerId: "deepseek", endpoint: "https:\/\/api\.deepseek\.com\/chat\/completions"/);
  const server = read("server.js");
  assert.match(server, /Authorization: req\.headers\.authorization \|\| `Bearer \$\{SUPABASE_ANON_KEY\}`/);
  assert.match(app, /\/api\/settings\/preferences/);
  assert.match(app, /\/api\/settings\/feedback/);
  assert.match(settingsClient, /diagnostics:/);
  assert.match(settingsClient, /recordDiagnostic:/);
  assert.match(app, /desktopDiagnostics\.log/);
  assert.match(app, /function collectDiagnosticSnapshot\(\)/);
  assert.match(app, /coordinateContract: \{ origin: "canvas-center"/);
  assert.match(app, /evaluatedProps: safe\(evaluated/);
  assert.match(app, /keyframes: safe\(clip\.keyframes/);
  assert.match(app, /transitionIn: safe\(clip\.transitionIn/);
  assert.match(app, /snapshot: desktopDiagnostics\.snapshot/);
  assert.match(app, /本地路径已隐藏/);
  assert.match(app, /keyframeEvaluations/);
  assert.match(app, /exportRuns/);
  assert.match(app, /timeline_add/);
  assert.match(app, /property_edit/);
  assert.match(aiClient, /ai_request promptLength/);
  assert.match(app, /recordFablecutDiagnostic/);
  assert.match(html, /id="setPreferenceStorage"/);
  assert.doesNotMatch(html, /id="setPreferenceDatabase"/);
  assert.match(html, /data-settings-tab="logs">日志/);
  assert.match(html, /data-settings-tab="feedback">意见反馈/);
  assert.doesNotMatch(html, /data-settings-tab="debug"/);
  assert.match(html, /id="modelProviderList"/);
  assert.match(html, /id="modelProviderDetail"/);
  assert.match(app, /async function loadProviderPresets/);
  assert.match(app, /function renderProviderCards/);
  assert.match(app, /makeAction\("设为默认"/);
  assert.match(app, /makeAction\("测试"/);
  assert.match(app, /function showProviderDetail/);
  assert.match(app, /setProviderDetailsEditable/);
  assert.match(app, /btnShowProviderForm.*?loadProviderPresets/s);
  assert.match(html, /<details class="provider-details" id="providerDetails">/);
  assert.match(html, /id="setAiModelCatalog"[\s\S]*?id="btnTestProvider"[\s\S]*?id="btnFetchModels"[\s\S]*?id="btnAddProvider"[\s\S]*?<details class="provider-details"/);
  assert.match(css, /width: min\(480px/);
  assert.match(css, /height: min\(548px/);
  assert.match(css, /#settingsLogsPanel \.diagnostic-log/);
  assert.match(css, /#btnReportError, \.dialog\.settings #btnSendFeedback/);
  assert.match(css, /\.settings-path-row input \{ appearance:none/);
  assert.match(css, /font-size:10px; line-height:1\.2/);
  assert.match(css, /#settingsFeedbackPanel \.feedback-field textarea \{ flex:1 1 auto/);
  assert.match(html, /id="btnAddProvider"[\s\S]*?<\/section>\s*<section class="settings-panel hidden" id="settingsPreferencesPanel"/);
});

test("authenticated resource requests consume the login session token", () => {
  const html = read("index.html");
  const app = read("app.js");
  const server = read("server.js");
  const css = read("style.css");
  assert.match(app, /localStorage\.setItem\("fablecut-auth-session", JSON\.stringify\(value\)\)/);
  assert.match(app, /Authorization:\s*`Bearer \$\{session\.access_token\}`/);
  assert.match(app, /fetchResourceApi\(`\/api\/resources\/catalog/);
  assert.match(app, /async function restoreAuthSession\(\)/);
  assert.match(app, /async function loadPersistedAuthSession\(\)/);
  assert.match(app, /window\.edwardSettings\?\.authSession/);
  assert.match(app, /window\.edwardSettings\?\.saveAuthSession/);
  assert.match(app, /window\.edwardSettings\?\.clearAuthSession/);
  assert.match(app, /function bootstrapAuthState\(attempt = 0\)/);
  assert.match(app, /window\.addEventListener\("load"/);
  assert.match(app, /setInterval\(async \(\) =>/);
  assert.match(app, /\/api\/auth\/refresh/);
  assert.match(app, /\/api\/auth\/session/);
  assert.match(server, /p === "\/api\/auth\/session" && req\.method === "GET"/);
  assert.match(server, /supabaseProxy\("\/auth\/v1\/user", req\)/);
  assert.match(app, /if \(!response\.ok\) throw new Error\("session invalid"\)/);
  assert.match(app, /setAuthButton\(session\);\s*return session;/);
  assert.doesNotMatch(app, /function bootstrapAuthState\(attempt = 0\) \{\s*setAuthButton\(storedAuthSession\(\)\)/);
  assert.match(app, /\/api\/auth\/entitlements/);
  assert.match(app, /function activeEntitlement\(value\)/);
  assert.match(app, /const active = activeEntitlement\(entitlements\)/);
  assert.match(app, /async function openSubscriptionPanel\(\)/);
  assert.match(app, /function formatBillingCycle\(interval, count = 1\)/);
  assert.match(app, /if \(n === 3\) return "季付"/);
  assert.match(app, /const cycle = formatBillingCycle\(plan.billing_interval, plan.billing_interval_count\)/);
  assert.match(app, /setAuthButton\(value\); closeAuth\(\);[\s\S]*await openSubscriptionPanel\(\)/);
  assert.match(app, /localStorage\.removeItem\("fablecut-auth-session"\)/);
  assert.match(app, /\/api\/subscription\/catalog/);
  assert.match(app, /\/api\/payment\/alipay/);
  assert.match(app, /beginSubscriptionPayment\.keys = new Map\(\)/);
  assert.match(app, /idempotencyKey = beginSubscriptionPayment\.keys\.get\(planKey\) \|\| crypto\.randomUUID\(\)/);
  assert.match(app, /beginSubscriptionPayment\.busy = false/);
  assert.match(app, /beginSubscriptionPayment\.keys\.delete\(planKey\)/);
  assert.match(app, /function paymentErrorMessage\(code\)/);
  assert.match(app, /已有一笔支付订单正在创建，请稍后点击方案重试。/);
  assert.match(app, /该支付订单已关闭，请重新选择订阅方案。/);
  assert.match(app, /startedAt: Date\.now\(\)/);
  assert.match(app, /支付等待已超时，请重新选择订阅方案。/);
  const alipayCreateOrder = fs.readFileSync(path.resolve(root, "..", "..", "supabase", "functions", "alipay-create-order", "index.ts"), "utf8");
  assert.match(alipayCreateOrder, /calculateOrderAmounts/);
  assert.match(alipayCreateOrder, /\.eq\("idempotency_key", idempotencyKey\)\.eq\("user_id", user\.id\)/);
  assert.match(alipayCreateOrder, /qrCode: existing\.provider_qr_code/);
  assert.match(alipayCreateOrder, /payment_order_retryable/);
  assert.match(alipayCreateOrder, /const timeoutExpress = "30m"/);
  assert.match(alipayCreateOrder, /timeout_express: timeoutExpress/);
  assert.match(alipayCreateOrder, /eq\("provider", "alipay"\)\.eq\("status", "pending"\)/);
  assert.match(alipayCreateOrder, /error\.code === "23505"/);
  assert.match(alipayCreateOrder, /Date\.now\(\) - Date\.parse\(existing\.created_at\) > 30_000/);
  assert.match(alipayCreateOrder, /Date\.now\(\) - Date\.parse\(existing\.created_at\) >= 30 \* 60 \* 1000/);
  assert.match(alipayCreateOrder, /const orderIdempotencyKey = existingExpired \? crypto\.randomUUID\(\) : idempotencyKey/);
  assert.match(alipayCreateOrder, /idempotency_key: orderIdempotencyKey/);
  assert.match(alipayCreateOrder, /Date\.now\(\) - Date\.parse\(pendingOrder\.created_at\) >= 30 \* 60 \* 1000/);
  assert.match(alipayCreateOrder, /Date\.now\(\) - Date\.parse\(pendingOrder\.created_at\) > 30_000/);
  const pendingGuard = fs.readFileSync(path.resolve(root, "..", "..", "supabase", "migrations", "202609190002_alipay_pending_order_guard.sql"), "utf8");
  assert.match(pendingGuard, /created_at < now\(\) - interval '30 minutes'/);
  assert.match(pendingGuard, /orders_alipay_one_pending_plan_per_user_idx/);
  const unifiedEntitlement = fs.readFileSync(path.resolve(root, "..", "..", "supabase", "migrations", "202609200002_unified_user_entitlement_timeline.sql"), "utf8");
  assert.match(unifiedEntitlement, /where user_id = o\.user_id/);
  assert.doesNotMatch(unifiedEntitlement, /where user_id = o\.user_id and plan_id = o\.plan_id/);
  assert.match(unifiedEntitlement, /select min\(current_period_start\) into first_paid_at/);
  assert.match(unifiedEntitlement, /when 'month' then start_at \+ make_interval\(months => p\.billing_interval_count\)/);
  const alipayQueryOrder = fs.readFileSync(path.resolve(root, "..", "..", "supabase", "functions", "alipay-query-order", "index.ts"), "utf8");
  assert.match(alipayQueryOrder, /TRADE_CLOSED/);
  assert.match(alipayQueryOrder, /status: "expired"/);
  assert.match(app, /\/api\/payment\/alipay\/state/);
  assert.match(app, /请使用支付宝扫码支付。/);
  assert.match(app, /watchSubscriptionPayment/);
  assert.match(app, /checkSubscriptionPaymentNow/);
  assert.match(app, /reconcileSubscriptionPayment/);
  assert.doesNotMatch(app, /text\/event-stream/);
  assert.doesNotMatch(app, /\/api\/payment\/alipay\/events/);
  assert.match(html, /id="subscriptionOverlay"/);
  assert.match(html, /id="btnAuthLogout"/);
  assert.match(app, /quickchart\.io\/qr/);
  assert.match(app, /api\.qrserver\.com\/v1\/create-qr-code/);
  assert.match(app, /button\.style\.background = signedIn \? "#1aa6a6"/);
  assert.match(app, /button\.dataset\.authenticated = signedIn \? "true" : "false"/);
  assert.match(app, /setAuthState/);
  assert.match(read("settings-client.js"), /authSession: \(\) => call\("fablecutAuthSession"\)/);
  assert.match(css, /subscription-banner[^{]*\{[^}]*aspect-ratio:16 \/ 9/s);
  assert.match(css, /subscription-dialog[^{]*\{[^}]*overflow:auto/);
});

test("default provider is visually synchronized with the AI assistant", () => {
  const html = read("index.html");
  const app = read("app.js");
  const css = read("style.css");
  assert.match(html, /id="inspectorAiProvider"/);
  assert.match(app, /function syncAiAssistantProvider/);
  assert.match(app, /card\.classList\.toggle\("is-default-provider"/);
  assert.match(css, /\.provider-card\.is-default-provider/);
  assert.match(css, /\.inspector\.ai-thinking \.inspector-ai::before/);
});

test("a single fetched model is persisted as the default model", () => {
  const app = fs.readFileSync(path.join(root, "app.js"), "utf8");
  assert.match(app, /result\.values\.length === 1/);
  assert.match(app, /自动设为默认模型并保存/);
  assert.match(app, /window\.edwardSettings\.save\(\$\("setAiProviderId"\)/);
});

test("top bar uses only the connection dot when connected", () => {
  const html = read("index.html");
  const app = read("app.js");
  assert.doesNotMatch(html, /connected<\/span>/);
  assert.match(app, /status\.textContent = connected \? "" : "未连接"/);
  assert.match(app, /els\.projectName\.append\(name, status\)/);
});
